package com.nextrade.engine.risk; import com.nextrade.common.enumtype.RiskSeverity; public record RiskDecision(boolean allowed,RiskSeverity severity,String code,String message){public static RiskDecision allow(){return new RiskDecision(true,RiskSeverity.INFO,"OK","Allowed");}public static RiskDecision block(String c,String m){return new RiskDecision(false,RiskSeverity.BLOCK,c,m);}}
